from review import card,save,DATE

i='TCS-3079';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 2, pp. 55:2–55:3 (the two logics, binary encoding, p-existence and Theorems 1–2); Section 6, p. 55:14 (improving the NEXP upper bounds).'
refs.extend([dict(id='infinity',title='Effective Quantifier Elimination for Presburger Arithmetic with Infinity',authors='Aless Lasaruk; Thomas Sturm',year=2009,url='https://doi.org/10.1007/978-3-642-04103-7_18',locator='CASC 2009, pp. 195–212; reference 17 of the primary paper, invoked there for the semantics of linear terms containing infinity. Bibliographic record and abstract checked, but the full text was unavailable in this review.'),dict(id='restricted2025',title='Polynomial-Time Tractable Problems over the p-Adic Numbers',authors='Manuel Bodirsky; Arno Fehm',year=2025,url='https://doi.org/10.4230/LIPIcs.MFCS.2025.25',locator='Introduction and Sections 2, 4–6: restricted valuation constraints at specified primes; explicit comparison with Haase–Mansutti in Related Work.')])
issue='The full semantics for linear valuation terms containing ∞ must be recovered from the primary paper’s reference 17; its axiom system was not available in full during this review, so ordinary extended-real arithmetic is not silently substituted. In addition, “improve NEXP” does not specify a target class or a quantitative time bound; the source should be preserved as a complexity-classification question until the intended completion criterion is fixed.'
save(i,dict(title='Complexity of choosing a satisfying base in Büchi and p-adic linear arithmetic',formal='Determine the computational complexity of p-existence for each of the two existential logics below. Given one existential formula Φ containing the symbolic base parameter p, decide whether Φ has a satisfying assignment for some integer p≥2 in Büchi arithmetic, or for some prime p in linear arithmetic over p-adic integers. The source proves an NEXP upper bound in both cases and asks whether these bounds can be improved. It does not nominate NP, subexponential time, or another specific improvement. The p-adic infinity conventions and the exact requested complexity precision remain to be fully specified as recorded below.',definitions='An existential formula is an existential quantifier prefix followed by a quantifier-free Boolean combination of atomic formulas; negation, conjunction and disjunction are allowed. For Büchi arithmetic the domain is ℕ={0,1,…}, the language has constants 0,1, addition, equality and the unary function V_p. For x>0, V_p(x)=p^k where k is the largest nonnegative integer for which p^k divides x; V_p(0)=1. The base p can be composite. For the p-adic variant, p is prime: for a nonzero rational a/b, v_p(a/b) is the exponent of p in a minus that in b. Set |x|_p=p^{−v_p(x)} and |0|_p=0; ℚ_p is the completion of ℚ in this absolute value, and ℤ_p={x∈ℚ_p:v_p(x)≥0}. The valuation extends to ℚ_p and v_p(0)=∞. The logic has two sorts ℤ_p and Z̄=ℤ∪{∞}, constants 0,1 and addition within each sort, equality within each sort, order < on Z̄, and v_p:ℤ_p→Z̄. Finite integers lie below ∞. There is no multiplication of two variables in either logic. Linear constraints may have integer coefficients and constants written in binary, with signed values only where meaningful in the given sort. Semantics of valuation terms involving ∞ are delegated by the source to its cited axiom system and are not yet fully reproduced here. The input is a finite formula with explicit syntax and binary numerals; N is its total bit length. The parameter p itself is not supplied as a binary input integer: v_p or V_p counts as one function symbol, used with the same unknown p throughout Φ. The algorithm decides yes or no, not a numeric approximation, in the uniform Turing bit model. NEXP means nondeterministic time 2^{N^{O(1)}}; no randomized error guarantee replaces correctness.',question_type='asymptotic_complexity',answer_criterion='Give a complexity classification for each full p-existence problem under the recovered source semantics, with upper and hardness bounds that settle the chosen precision. Before certifying a complete benchmark target, finish the infinity conventions and specify what degree of improvement or classification is required. Hardness of p-universality alone does not answer p-existence.',context_blocks=[dict(title='The base is itself existentially chosen',text='The formula is fixed as input, but a satisfying interpretation may exist at only some bases. In the p-adic case those bases must be prime; in Büchi arithmetic all integers at least two are eligible. These are different domains within the same base-selection question.',citation='primary'),dict(title='Valuations add expressive power to linear arithmetic',text='The formulas can combine addition with constraints on divisibility by powers of the base. In the p-adic language the constraints may compare arbitrary linear expressions in valuations, a broader task than imposing a fixed valuation on each variable.',citation='primary'),dict(title='Existence is not the complement of universality',text='The proved coNEXP-completeness result for Büchi arithmetic concerns satisfiability at every base. Negating that outer universal quantifier yields a base where the formula has no satisfying assignment, rather than a base where it does. It therefore does not supply the missing hardness result here.',citation='primary'),dict(title='Later restricted cases do not settle base selection',text='The 2025 work gives polynomial-time and NP-completeness results for restricted systems at specified primes, including different behavior at primes two and three. It distinguishes these restrictions from the more expressive Haase–Mansutti setting and does not claim a matching classification for the two full p-existence problems.',citation='restricted2025'),dict(title='Remaining formulation work',text=issue)],why='Would determine the cost of choosing a number-theoretic base while solving linear constraints, clarifying how parametric divisibility changes otherwise well-understood existential arithmetic.',references=refs,progress=[dict(date='2021',text='Both p-existence problems are shown to lie in NEXP; the conclusion asks whether those upper bounds can be improved.',citation='primary'),dict(date='2025',text='Restricted valuation-constraint systems at specified primes receive sharper classifications, with a different scope from full p-existence.',citation='restricted2025')],status='source_open',status_note='Read the complete MFCS 2021 paper, its author copy and the relevant MFCS 2025 follow-up sections. Searches through 12 September 2026 found no resolution of the two unrestricted p-existence complexity questions. The cited infinity axiom system could not be read in full, so formulation review remains unfinished.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered both base domains, input encoding, quantifier order and the distinction from universality.']),importance=dict(score=c['importance']['score'],method='editorial',reason='A structural boundary for symbolic arithmetic when divisibility bases vary, connecting satisfiability and parameter-dependent number systems. Existing score retained.',assessed_on=DATE),review_note='Replaced the isolated NEXP sentence with both actual decision problems and their encoding. Avoided transferring universality hardness, assuming a target NP bound or inventing infinity arithmetic.',working_summary=dict(sentences=['The input is an existential linear-arithmetic formula with a symbolic base p.','The decision asks whether some base makes that formula satisfiable.','Büchi arithmetic allows every integer base at least two, whereas the p-adic variant allows primes.','The source proves NEXP upper bounds and does not obtain the missing classification from its universality hardness theorem.','The exact desired complexity precision and the cited infinity conventions remain to be completed.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','infinity','restricted2025'])),notes=['Recovered the two p-existence problems, their base quantifiers and binary input model.','Separated existence from universality and from specified-prime restricted systems.','Recorded the inaccessible infinity semantics and the unspecified improvement target instead of substituting a new problem.'],checked_sources=[r['url'] for r in refs]+['https://www.cs.ox.ac.uk/people/christoph.haase/home/publication/hm-21/hm-21.pdf','https://science.thomas-sturm.de/publications/'],state='improved_unfinished')
